#!/usr/bin/env python3
"""Патч документации по итогам беседы L.3 (язык интерфейса it, итальянский).

Беседа целиком (2026-11-27; пишется одним коммитом). Идемпотентный: каждая
правка проверяет наличие нового текста (marker) и уходит в skip при
повторном прогоне. Отчёт applied/skip/fail. Запуск из корня репозитория:
    python3 scripts/patches/patch-docs-convL3.py

  L3/A  NEXT-CONTEXT: снимок «Состояние» ПЕРЕПИСАН (L.3 закрыта; прежний —
        в 08 Часть V), ближайшая по справке — L.4.
  L3/B  07: шаблон L — пункт 3 (подписи журнала сокращать), тестовый запрос
        плюралов на 10⁶, грабли L.3; указатель «По факту L.3»; строка L.3
        справки кандидатов.
  L3/C  08: Часть I — абзац L.3; Часть II — глава «Беседа L.3» с тремя
        подразделами «По факту»; Часть V — снимок после L.2.
  L3/D  09: §4 — уроки L.3; §10 — «Что L.3 оставила знать».
  L3/E  05: test-L-requests — и на it.
  L3/F  README — строка типовой беседы L; scripts/i18n/README — it утверждён.
"""
from __future__ import annotations

import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent.parent
PNC = ROOT / "NEXT-CONTEXT.md"
P07 = ROOT / "docs/07-conversation-protocol.md"
P08 = ROOT / "docs/08-history.md"
P09 = ROOT / "docs/09-lessons.md"
P05 = ROOT / "docs/05-file-structure.md"
PRM = ROOT / "README.md"
PI18N = ROOT / "scripts/i18n/README.md"

applied = 0
skipped = 0
failed = 0


def patch(path: Path, old: str, new: str, label: str, marker: str | None = None) -> None:
    """Заменяет old → new; идемпотентность — по marker (или new) в тексте."""
    global applied, skipped, failed
    text = path.read_text(encoding="utf-8")
    probe = marker if marker is not None else new
    if probe in text:
        print(f"  skip  {label}")
        skipped += 1
        return
    if text.count(old) != 1:
        print(f"  FAIL  {label}: якорь встречается {text.count(old)} раз")
        failed += 1
        return
    path.write_text(text.replace(old, new), encoding="utf-8")
    print(f"  ok    {label}")
    applied += 1


